import functools
import inspect
from typing import Any, Callable, Dict, ForwardRef, Union, Optional, List
from fastapi.dependencies.utils import get_typed_signature

def test_wrapped_forward_ref():
    class Model:
        pass

    def my_endpoint(param: 'Model'):
        return param

    @functools.wraps(my_endpoint)
    def wrapped_endpoint(param: 'Model'):
        return my_endpoint(param)

    # We need to make sure 'Model' is NOT in the globals of the wrapper's environment
    # but IS in the globals of the wrapped function's environment.
    # Since they are in the same module here, they share globals.
    # Let's use a different approach.

    # Create a function in a different "module" (using a function as a closure)
    def create_wrapped():
        class LocalModel:
            pass

        def original(param: 'LocalModel'):
            return param

        @functools.wraps(original)
        def wrapper(param: 'LocalModel'):
            return original(param)

        return wrapper, LocalModel

    wrapped, LocalModel = create_wrapped()

    try:
        get_typed_signature(wrapped)
        print("Success!")
    except NameError as e:
        print(f"Caught expected NameError: {e}")
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_wrapped_forward_ref()

